3	
4	// DeepSpeed Team
5	
6	#include <cstring>
7	#include <stdexcept>
8	#include "fp_context.h"
9	#include "fp_quantize.h"
10	#include "memory_access_utils.h"
11	#include "reduction_utils.h"
12	
13	#include <cuda.h>
14	#include <stdint.h>
15	
16	#include <cuda_fp16.h>
17	#include <curand_kernel.h>
18	
19	#ifdef BF16_AVAILABLE
20	#include <cuda_bf16.h>
21	#endif
22	#include <cuda_runtime_api.h>
23	
24	using ROp = reduce::ROpType;
25	
26	namespace quantization {
27	
28	constexpr int access_granularity = 16;
29	constexpr int quanitzed_access_granularity = 4;
30	constexpr int quanitzed_access_granularity_6bits = 2;
31	constexpr int threads = 256;
32	constexpr int warps = threads / 32;
33	
34	}  // namespace quantization
35	
36	template <int _mantisa_bits, int q_mantisa_bits, int stochastic_rounding>
37	__device__ void round(uint32_t& mantisa, uint32_t& dst_exponent, curandStatePhilox4_32_10_t* state)
38	{
39	    constexpr uint32_t mantisa_mask = (1U << (_mantisa_bits - q_mantisa_bits)) - 1;
40	    uint32_t offset = stochastic_rounding ? (curand_poisson(state, 10) & mantisa_mask)
41	                                          : 1U << (_mantisa_bits - q_mantisa_bits - 1);
42	    mantisa += offset;
43	    dst_exponent += (((mantisa & ~mantisa_mask) == (1U << _mantisa_bits)) ? 1 : 0);
44	}
45	
46	template <int _mantisa_bits, int _exponent_bits, int q_mantisa_bits, int q_exponent_bits>
47	__device__ void clip(uint32_t& exponent, uint32_t& mantisa)
48	{
49	    constexpr uint32_t max_exponent = (1 << (q_exponent_bits - 1)) + (1 << (_exponent_bits - 1));
50	    constexpr uint32_t min_exponent =
51	        (1 << (_exponent_bits - 1)) - ((1 << (q_exponent_bits - 1)) - 1);
52	    if (exponent > max_exponent) {
53	        exponent = max_exponent;
54	        mantisa = (((uint32_t)-1) >> (32 - q_mantisa_bits)) << 1;  //.11 .. 10
55	    }
56	    if (exponent < min_exponent) {
57	        exponent = min_exponent;
58	        mantisa = 0;
59	    }
60	}
61	
62	template <typename T,
63	          int unroll,
64	          int _mantisa_bits,
65	          int _exponent_bits,
66	          int total_q_bits = 8,
67	          int q_mantisa_bits = 3,
68	          int stochastic_rounding = 0>
69	__global__ void apply_quantization(T* val,
70	                                   uint8_t* q_val,
71	                                   int group_size,
72	                                   std::pair<uint64_t, uint64_t> seed,
73	                                   float q_range)
74	{
75	    int tidx = threadIdx.x;
76	    int wid = tidx >> 5;
77	    int lane = tidx & 0x1f;
78	    int gid = blockIdx.x * quantization::warps + wid;
79	
80	    constexpr int q_exponent_bits = total_q_bits - q_mantisa_bits - 1;
81	    constexpr uint32_t _mantisa_mask = (1 << _mantisa_bits) - 1;
82	    constexpr uint32_t _exponent_mask = ((1 << _exponent_bits) - 1) << _mantisa_bits;
83	    constexpr uint32_t _sign_mask = 1U << (_mantisa_bits + _exponent_bits);
84	    // Biased (source format) exponent of the smallest normal of the quantized format.
85	    constexpr uint32_t q_min_normal_exponent =
86	        (1 << (_exponent_bits - 1)) - ((1 << (q_exponent_bits - 1)) - 1);
87	    const float q_min_normal = __uint_as_float(q_min_normal_exponent << _mantisa_bits);
88	    // CG helpers
89	    cg::thread_block tb = cg::this_thread_block();
90	    cg::thread_block_tile<hw_warp_size> warp = cg::tiled_partition<hw_warp_size>(tb);
91	
92	    constexpr uint32_t vector_size = quantization::access_granularity / sizeof(T);
93	    constexpr uint32_t load_stride = vector_size * hw_warp_size;
94	    constexpr uint32_t store_stride = (total_q_bits * vector_size / 8) * hw_warp_size;
95	    const uint32_t thread_offset = lane * vector_size;
96	    const uint32_t store_thread_offset = lane * (total_q_bits * vector_size / 8);
97	    const uint32_t base_load_offset = gid * group_size + thread_offset;
98	    const uint32_t base_store_offset =
99	        gid * ((group_size * total_q_bits / 8) + 4) +
100	        store_thread_offset;  // 4-byte for saving the scale per group
101	    const T* load_base_ptr = val + base_load_offset;
102	    T tmp_buf[unroll * vector_size];
103	    T cur_max;
104	    reduce::init<ROp::Max>(&cur_max);
105	
106	    int idx = blockIdx.x * blockDim.x + threadIdx.x;
107	    curandStatePhilox4_32_10_t state;
108	    curand_init(seed.first, idx, seed.second, &state);
109	
110	#pragma unroll
111	    for (int i = 0; i < unroll; i++) {
112	        if (i * load_stride + thread_offset < group_size) {
113	            mem_access::load_global<quantization::access_granularity>(
114	                &tmp_buf[vector_size * i], load_base_ptr + i * load_stride);
115	            for (int j = 0; j < vector_size; j++)
116	                cur_max = reduce::element<ROp::Max>(cur_max, __habs(tmp_buf[i * vector_size + j]));
117	        }
118	    }
119	    reduce::_block<T, 1, ROp::Max>(tb, warp, &cur_max);
120	
121	    int mantisa_mask = ((1 << q_mantisa_bits) - 1);
122	    mantisa_mask <<= (_mantisa_bits - q_mantisa_bits);
123	
124	    uint8_t* store_base_ptr = q_val + base_store_offset;
125	    float scale = (float)q_range / conversion::to<float>(cur_max);
126	#pragma unroll
127	    for (int i = 0; i < unroll; i++) {
128	        if (i * load_stride + thread_offset < group_size) {
129	            uint64_t q_buf = 0;
130	            uint64_t q_buf1 = 0;
131	#pragma unroll
132	            for (int j = 0; j < vector_size; j++) {
133	                float val_f = conversion::to<float>(tmp_buf[i * vector_size + j]) * scale;
134	                uint32_t* data = reinterpret_cast<uint32_t*>(&val_f);
135	                uint32_t sign = (data[0] & _sign_mask) >> (_mantisa_bits + _exponent_bits);
136	                uint32_t cur_exponent = (data[0] & _exponent_mask) >> _mantisa_bits;
137	                uint32_t dst_mantisa = (data[0] & _mantisa_mask);
138	
139	                uint32_t dst_exponent = cur_exponent;
140	
141	                if (cur_exponent < q_min_normal_exponent) {
142	                    // Zero and values below the smallest normal use exponent field 0, whose
143	                    // steps are uniform like IEEE subnormals. Adding the smallest normal fixes
144	                    // the exponent, so the shared rounding lands on that step; a carry means
145	                    // the value rounded up to the smallest normal (field 1).
146	                    float shifted = fabsf(val_f) + q_min_normal;
147	                    dst_mantisa = __float_as_uint(shifted) & _mantisa_mask;
148	                    dst_exponent = q_min_normal_exponent;
149	                    round<_mantisa_bits, q_mantisa_bits, stochastic_rounding>(
150	                        dst_mantisa, dst_exponent, &state);
151	                    dst_exponent -= q_min_normal_exponent;
152	                } else {
153	                    round<_mantisa_bits, q_mantisa_bits, stochastic_rounding>(
154	                        dst_mantisa, dst_exponent, &state);
155	                    clip<_mantisa_bits, _exponent_bits, q_mantisa_bits, q_exponent_bits>(
156	                        dst_exponent, dst_mantisa);
157	
158	                    if (dst_exponent != (1 << q_exponent_bits) - 1)
159	                        dst_exponent = (dst_exponent - ((1 << (_exponent_bits - 1)) - 1)) +
160	                                       (1 << (q_exponent_bits - 1)) - 1;
161	                }
162	
163	                dst_mantisa = (dst_mantisa & mantisa_mask) >> (_mantisa_bits - q_mantisa_bits);
164	                if (total_q_bits == 8 || total_q_bits == 4 || total_q_bits == 6)
165	                    q_buf = q_buf |
166	                            ((uint64_t)((uint8_t)(sign << (q_exponent_bits + q_mantisa_bits) |
167	                                                  (dst_exponent << q_mantisa_bits) | dst_mantisa))
168	                             << j * total_q_bits);
169	                else if (total_q_bits == 12) {
170	                    if (j < 5)
171	                        q_buf =
172	                            q_buf |
173	                            ((uint64_t)((uint16_t)(sign << (q_exponent_bits + q_mantisa_bits) |
174	                                                   (dst_exponent << q_mantisa_bits) | dst_mantisa))
175	                             << j * total_q_bits);
176	                    else
177	                        q_buf1 =
178	                            q_buf1 |
179	                            ((uint64_t)((uint16_t)(sign << (q_exponent_bits + q_mantisa_bits) |
180	                                                   (dst_exponent << q_mantisa_bits) | dst_mantisa))
181	                             << (j - 5) * total_q_bits);
182	                }
183	            }
184	            if (total_q_bits == 12) {
185	                uint64_t last_nibble_mask = 0xf;
186	                last_nibble_mask = q_buf1 & last_nibble_mask;
187	                q_buf = (last_nibble_mask << 60) | q_buf;
188	                q_buf1 >>= 4;
189	            }
190	            uint8_t* int8_data = reinterpret_cast<uint8_t*>(&q_buf);
191	            uint8_t* int8_data1 = reinterpret_cast<uint8_t*>(&q_buf1);
192	            if (total_q_bits == 6) {
193	                mem_access::store_global<quantization::quanitzed_access_granularity_6bits>(
194	                    store_base_ptr + i * store_stride, int8_data);
195	                mem_access::store_global<quantization::quanitzed_access_granularity_6bits>(
196	                    store_base_ptr + i * store_stride +
197	                        quantization::quanitzed_access_granularity_6bits,
198	                    int8_data + quantization::quanitzed_access_granularity_6bits);
199	                mem_access::store_global<quantization::quanitzed_access_granularity_6bits>(
200	                    store_base_ptr + i * store_stride +
201	                        quantization::quanitzed_access_granularity_6bits * 2,
202	                    int8_data + 2 * quantization::quanitzed_access_granularity_6bits);
203	            } else {
204	                mem_access::store_global<quantization::quanitzed_access_granularity>(
205	                    store_base_ptr + i * store_stride, int8_data);
206	
207	                if (total_q_bits > 4) {
208	                    mem_access::store_global<quantization::quanitzed_access_granularity>(
209	                        store_base_ptr + i * store_stride +
210	                            quantization::quanitzed_access_granularity,
211	                        int8_data + quantization::quanitzed_access_granularity);
212	                    if (total_q_bits == 12) {
213	                        mem_access::store_global<quantization::quanitzed_access_granularity>(
214	                            store_base_ptr + i * store_stride +
215	                                quantization::quanitzed_access_granularity * 2,
216	                            int8_data1);
217	                    }
218	                }
219	            }
220	        }
221	    }
222	    if (lane == 0) {
223	        float q_scale = conversion::to<float>(cur_max) / (float)q_range;
224	        uint8_t* scale_as_int8 = reinterpret_cast<uint8_t*>(&q_scale);
225	        uint32_t scale_offset =
226	            gid * ((group_size * total_q_bits / 8) + 4) + (group_size * total_q_bits / 8);
227	        if (total_q_bits != 6)
228	            mem_access::store_global<quantization::quanitzed_access_granularity>(
229	                q_val + scale_offset, scale_as_int8);
230	        else {
231	            mem_access::store_global<quantization::quanitzed_access_granularity_6bits>(
232	                q_val + scale_offset, scale_as_int8);
233	            mem_access::store_global<quantization::quanitzed_access_granularity_6bits>(
234	                q_val + scale_offset + quantization::quanitzed_access_granularity_6bits,
235	                scale_as_int8 + quantization::quanitzed_access_granularity_6bits);
236	        }
237	    }
238	}
