240	template <typename T,
241	          int mantisa_bits,
242	          int total_q_bits = 16,
243	          int q_mantisa_bits = 3,
244	          int q_exponent_bits = 4>
245	__global__ void apply_dequantization(uint8_t* val, T* q_val, int group_size, int total_num_elements)
246	{
247	    constexpr uint32_t vector_size = quantization::access_granularity / sizeof(T);
248	    int tidx = (blockIdx.x * blockDim.x + threadIdx.x) * vector_size;
249	
250	    // Packed bits use the quantized exponent width. The restored bf16/fp16 value uses its own.
251	    constexpr int dst_exponent_bits = total_q_bits - mantisa_bits - 1;
252	    constexpr int quantized_bits = q_mantisa_bits + q_exponent_bits + 1;
253	    constexpr uint16_t _mantisa_mask = (1 << q_mantisa_bits) - 1;
254	    constexpr uint16_t _exponent_mask = ((1 << q_exponent_bits) - 1) << q_mantisa_bits;
255	    constexpr uint16_t _sign_mask = 1U << (q_mantisa_bits + q_exponent_bits);
256	    // Value of one mantissa step at exponent field 0: 2^(1 - bias - q_mantisa_bits).
257	    constexpr uint32_t q_subnormal_step_exponent =
258	        127 + 1 - ((1 << (q_exponent_bits - 1)) - 1) - q_mantisa_bits;
259	    const float q_subnormal_step = __uint_as_float(q_subnormal_step_exponent << 23);
260	    const uint32_t g_index = (tidx / group_size);
261	    const uint32_t group_size_bytes = (group_size * quantized_bits / 8);
262	    const uint8_t* load_base_ptr =
263	        val + g_index * (group_size_bytes + 4) + (tidx % group_size) * quantized_bits / 8;
264	
265	    T* store_base_ptr = q_val + tidx;
266	    float scale;
267	
268	    uint8_t* scale_as_int8 = reinterpret_cast<uint8_t*>(&scale);
269	    if (quantized_bits == 6) {
270	        mem_access::load_global<quantization::quanitzed_access_granularity_6bits>(
271	            scale_as_int8, val + g_index * (group_size_bytes + 4) + group_size_bytes);
272	        mem_access::load_global<quantization::quanitzed_access_granularity_6bits>(
273	            scale_as_int8 + quantization::quanitzed_access_granularity_6bits,
274	            val + g_index * (group_size_bytes + 4) + group_size_bytes +
275	                quantization::quanitzed_access_granularity_6bits);
276	    } else
277	        mem_access::load_global<quantization::quanitzed_access_granularity>(
278	            scale_as_int8, val + g_index * (group_size_bytes + 4) + group_size_bytes);
279	
280	    if (tidx < total_num_elements) {
281	        uint64_t q_buf_in;
282	        uint64_t q_buf_in1;
283	        uint8_t* int8_data = reinterpret_cast<uint8_t*>(&q_buf_in);
284	        uint8_t* int8_data1 = reinterpret_cast<uint8_t*>(&q_buf_in1);
285	        if (quantized_bits == 6) {
286	            mem_access::load_global<quantization::quanitzed_access_granularity_6bits>(
287	                int8_data, load_base_ptr);
288	            mem_access::load_global<quantization::quanitzed_access_granularity_6bits>(
289	                int8_data + quantization::quanitzed_access_granularity_6bits,
290	                load_base_ptr + quantization::quanitzed_access_granularity_6bits);
291	            mem_access::load_global<quantization::quanitzed_access_granularity_6bits>(
292	                int8_data + quantization::quanitzed_access_granularity_6bits * 2,
293	                load_base_ptr + quantization::quanitzed_access_granularity_6bits * 2);
294	
295	        } else {
296	            mem_access::load_global<quantization::quanitzed_access_granularity>(int8_data,
297	                                                                                load_base_ptr);
298	            if (quantized_bits > 4) {
299	                mem_access::load_global<quantization::quanitzed_access_granularity>(
300	                    int8_data + quantization::quanitzed_access_granularity,
301	                    load_base_ptr + quantization::quanitzed_access_granularity);
302	                if (quantized_bits == 12) {
303	                    mem_access::load_global<quantization::quanitzed_access_granularity>(
304	                        int8_data1, load_base_ptr + quantization::quanitzed_access_granularity * 2);
305	                }
306	            }
307	        }
308	        T store_buf[vector_size];
309	#pragma unroll
310	        for (int j = 0; j < vector_size; j++) {
311	            uint16_t new_data;
312	            if (j < 5 || quantized_bits != 12) {
313	                new_data = (uint16_t)(q_buf_in >> (j * quantized_bits));
314	            } else {
315	                if (j == 5) {
316	                    new_data = (uint16_t)(q_buf_in1);
317	                    new_data = (uint16_t)((new_data << 4) | (q_buf_in >> 60));
318	                } else
319	                    new_data = (uint16_t)(q_buf_in1 >> ((j - 6) * quantized_bits + 8));
320	            }
321	
322	            uint16_t sign = (new_data & _sign_mask) >> (q_mantisa_bits + q_exponent_bits);
323	            uint16_t dst_exponent = (new_data & _exponent_mask) >> q_mantisa_bits;
324	            uint16_t dst_mantisa = (new_data & _mantisa_mask);
325	
326	            float up_cast;
327	            if (dst_exponent == 0) {
328	                // Zero and subnormals have no implicit leading one.
329	                up_cast = dst_mantisa * q_subnormal_step;
330	                if (sign) up_cast = -up_cast;
331	            } else {
332	                dst_exponent = (dst_exponent - ((1 << (q_exponent_bits - 1)) - 1)) +
333	                               (1 << (dst_exponent_bits - 1)) - 1;
334	
335	                // memcpy keeps the packed bits visible to the typed load. A uint16
336	                // overlay of store_buf is not reliable under nvcc 13.
337	                uint16_t packed =
338	                    ((sign << (dst_exponent_bits + mantisa_bits)) | (dst_exponent << mantisa_bits) |
339	                     (dst_mantisa << (mantisa_bits - q_mantisa_bits)));
340	                memcpy(&store_buf[j], &packed, sizeof(packed));
341	                up_cast = conversion::to<float>(store_buf[j]);
342	            }
343	            store_buf[j] = conversion::to<T>(up_cast * scale);
344	        }
345	        mem_access::store_global<quantization::access_granularity>(store_base_ptr, store_buf);
346	    }
347	}
