349	#define LAUNCH_FOR_QUANTIZATION_UNROLL(COUNT)                                    \
350	    case COUNT:                                                                  \
351	        apply_quantization<T,                                                    \
352	                           COUNT,                                                \
353	                           mantisa,                                              \
354	                           exponent,                                             \
355	                           CONST_Q_BITS,                                         \
356	                           CONST_Q_MANTISA_BITS,                                 \
357	                           CONST_STOCHASTIC_ROUNDING>                            \
358	            <<<grid, block, 0, stream>>>(val, q_val, group_size, seed, q_range); \
359	        break;
360	
361	template <typename T, int mantisa, int exponent>
362	void launch_quantization(T* val,
363	                         uint8_t* q_val,
364	                         int num_groups,
365	                         int group_size,
366	                         cudaStream_t stream,
367	                         float q_range,
368	                         int q_bits,
369	                         int q_mantisa_bits,
370	                         int stochastic_rounding)
371	{
372	    const dim3 grid((num_groups + quantization::warps - 1) / quantization::warps);
373	    const dim3 block(quantization::threads);
374	
375	    std::pair<uint64_t, uint64_t> seed = FPContext::Instance().IncrementOffset(16);
376	
377	    constexpr int vals_per_unroll = hw_warp_size * quantization::access_granularity / sizeof(T);
378	
379	    const int copy_unroll = (group_size + vals_per_unroll - 1) / vals_per_unroll;
380	    QUANT_SWITCH((q_bits - q_mantisa_bits - 1) * q_mantisa_bits + stochastic_rounding, [&] {
381	        switch (copy_unroll) {
382	            LAUNCH_FOR_QUANTIZATION_UNROLL(1)
383	            LAUNCH_FOR_QUANTIZATION_UNROLL(2)
384	            LAUNCH_FOR_QUANTIZATION_UNROLL(3)
385	            LAUNCH_FOR_QUANTIZATION_UNROLL(4)
386	            LAUNCH_FOR_QUANTIZATION_UNROLL(5)
387	            LAUNCH_FOR_QUANTIZATION_UNROLL(6)
388	        }
389	    });
390	}
391	#define INSTANTIATE_LAUNCH_QUANTIZATION(T, mantisa, exponent) \
392	    template void launch_quantization<T, mantisa, exponent>(  \
393	        T*, uint8_t*, int, int, cudaStream_t, float q_range, int, int, int);
394	// fp8(E4M3), nearest-rounding
395	#ifdef BF16_AVAILABLE
396	INSTANTIATE_LAUNCH_QUANTIZATION(__nv_bfloat16, 23, 8);
397	#endif
398	INSTANTIATE_LAUNCH_QUANTIZATION(__half, 23, 8);
