400	template <typename T, int mantisa>
401	void launch_dequantization(uint8_t* val,
402	                           T* q_val,
403	                           int num_groups,
404	                           int group_size,
405	                           int q_mantisa_bits,
406	                           int q_exponent_bits,
407	                           cudaStream_t stream)
408	{
409	    int blocks = ((num_groups * group_size) - 1) /
410	                     (quantization::threads * (quantization::access_granularity / sizeof(T))) +
411	                 1;
412	    const dim3 grid(blocks);
413	    const dim3 block(quantization::threads);
414	    DEQUANT_SWITCH(q_mantisa_bits * q_exponent_bits, [&] {
415	        apply_dequantization<T, mantisa, 16, CONST_Q_MANTISA_BITS, CONST_Q_EXPONENT_BITS>
416	            <<<grid, block, 0, stream>>>(val, q_val, group_size, (num_groups * group_size));
417	    });
