447	    constexpr uint32_t q_subnormal_step_exponent =
448	        127 + 1 - ((1 << (q_exponent_bits - 1)) - 1) - q_mantisa_bits;
449	    const float q_subnormal_step = __uint_as_float(q_subnormal_step_exponent << 23);
450	    const uint32_t g_index = (input_index / group_size);
451	    const uint32_t group_size_bytes = (group_size * quantized_bits / 8);
