461	            scale_as_int8, val + g_index * (group_size_bytes + 4) + group_size_bytes);
462	        mem_access::load_global<quantization::quanitzed_access_granularity_6bits>(
463	            scale_as_int8 + quantization::quanitzed_access_granularity_6bits,
464	            val + g_index * (group_size_bytes + 4) + group_size_bytes +
465	                quantization::quanitzed_access_granularity_6bits);
466	    } else
467	        mem_access::load_global<quantization::quanitzed_access_granularity>(
468	            scale_as_int8, val + g_index * (group_size_bytes + 4) + group_size_bytes);
