471	        uint64_t q_buf_in;
472	        uint64_t q_buf_in1;
473	        uint8_t* int8_data = reinterpret_cast<uint8_t*>(&q_buf_in);
474	        uint8_t* int8_data1 = reinterpret_cast<uint8_t*>(&q_buf_in1);
475	        if (quantized_bits == 6) {
476	            mem_access::load_global<quantization::quanitzed_access_granularity_6bits>(
477	                int8_data, load_base_ptr);
478	            mem_access::load_global<quantization::quanitzed_access_granularity_6bits>(
479	                int8_data + quantization::quanitzed_access_granularity_6bits,
480	                load_base_ptr + quantization::quanitzed_access_granularity_6bits);
481	            mem_access::load_global<quantization::quanitzed_access_granularity_6bits>(
482	                int8_data + quantization::quanitzed_access_granularity_6bits * 2,
483	                load_base_ptr + quantization::quanitzed_access_granularity_6bits * 2);
484	        } else {
485	            mem_access::load_global<quantization::quanitzed_access_granularity>(int8_data,
486	                                                                                load_base_ptr);
487	            if (quantized_bits > 4) {
488	                mem_access::load_global<quantization::quanitzed_access_granularity>(
489	                    int8_data + quantization::quanitzed_access_granularity,
490	                    load_base_ptr + quantization::quanitzed_access_granularity);
