501	            if (j < 5 || quantized_bits != 12) {
502	                new_data = (uint16_t)(q_buf_in >> (j * quantized_bits));
503	            } else {
504	                if (j == 5) {
505	                    new_data = (uint16_t)(q_buf_in1);
506	                    new_data = (uint16_t)((new_data << 4) | (q_buf_in >> 60));
507	                } else
508	                    new_data = (uint16_t)(q_buf_in1 >> ((j - 6) * quantized_bits + 8));
509	            }
510	
511	            uint16_t sign = (new_data & _sign_mask) >> (q_mantisa_bits + q_exponent_bits);
512	            uint16_t dst_exponent = (new_data & _exponent_mask) >> q_mantisa_bits;
513	            uint16_t dst_mantisa = (new_data & _mantisa_mask);
514	
515	            float up_cast;
516	            if (dst_exponent == 0) {
517	                up_cast = dst_mantisa * q_subnormal_step;
518	                if (sign) up_cast = -up_cast;
519	            } else {
520	                dst_exponent = (dst_exponent - ((1 << (q_exponent_bits - 1)) - 1)) +
521	                               (1 << (dst_exponent_bits - 1)) - 1;
522	
523	                uint16_t packed =
524	                    ((sign << (dst_exponent_bits + mantisa_bits)) | (dst_exponent << mantisa_bits) |
525	                     (dst_mantisa << (mantisa_bits - q_mantisa_bits)));
526	                memcpy(&store_buf[j], &packed, sizeof(packed));
527	                up_cast = conversion::to<float>(store_buf[j]);
528	            }
529	            store_buf[j] = conversion::to<T>(up_cast * scale);
530	        }
531	        mem_access::store_global<quantization::access_granularity>(store_base_ptr, store_buf);
532	    }
