535	template <typename T, int mantisa>
536	void launch_selective_dequantization(uint8_t* val,
537	                                     T* q_val,
538	                                     int32_t* indexes,
539	                                     int num_groups,
540	                                     int group_size,
541	                                     int num_indexes,
542	                                     int q_mantisa_bits,
543	                                     int q_exponent_bits,
544	                                     cudaStream_t stream)
545	{
546	    int total_elements_per_index = (num_groups / num_indexes) * group_size;
547	    int blocks = (total_elements_per_index - 1) /
548	                     (quantization::threads * (quantization::access_granularity / sizeof(T))) +
549	                 1;
550	    const dim3 grid(num_indexes, blocks);
551	    const dim3 block(quantization::threads);
552	    DEQUANT_SWITCH(q_mantisa_bits * q_exponent_bits, [&] {
553	        apply_selective_dequantization<T, mantisa, 16, CONST_Q_MANTISA_BITS, CONST_Q_EXPONENT_BITS>
554	            <<<grid, block, 0, stream>>>(val, q_val, indexes, group_size, total_elements_per_index);
555	    });
556	}
